def checkTMPtag(baseTagPath="[default]Exchange/ArchitectureBuilder", name="TPM"):
	tagPath="{}/{}".format(baseTagPath,name)

	if system.tag.exists(tagPath):
		return True
	else:
		tag = {"dataType": "Document", "tagType": "AtomicTag", "name": name, "valueSource": "memory", "value":{}}
		collisionPolicy = "a"
		system.tag.configure(baseTagPath, [tag], collisionPolicy)
		return False


def getGWBasePath():
	"""
	Retrieves the base path of the Ignition Gateway's project parent folder.
	
	This function accesses the Ignition Gateway context to determine the directory
	where the project data is stored. It ensures that the path uses forward slashes
	for consistency across different operating systems.
	
	Returns:
	    str: The absolute path to the Ignition Gateway's project parent folder,
	    formatted with forward slashes.
	"""
	from com.inductiveautomation.ignition.gateway import IgnitionGateway
	context = IgnitionGateway.get()
	projectParentFolder = str(context.systemManager.dataDir.absoluteFile).replace("\\","/")
	return projectParentFolder


def getThirdPartyModules():
	"""Retrieves the third-party modules information from a Memory Tag.
	
	This function accesses the global variables and returns the third-party
	modules (TPM) data stored in the tag.
	
	Returns:
	    dict: The dictionary containing third-party modules information.
	"""
	return system.tag.readBlocking(["[default]Exchange/ArchitectureBuilder/TPM"])[0].value


def getFormattedTPM(tpmmodules):
	"""Formats third-party module information into a specific dictionary structure.
	
	This function takes a list of module dictionaries and reformats them into a
	new dictionary where each key is the module's name and each value is a
	dictionary containing the module's details. Each module detail dictionary
	includes the image, author, price, link, id, description, and a selected
	flag set to False.
	
	Args:
	    modules (list): A list of dictionaries, where each dictionary contains
	                    information about a third-party module. Each dictionary
	                    must have the keys "name", "image", "author", "price",
	                    "link", "id", and "desc".
	
	Returns:
	    dict: A dictionary where each key is a module's name and each value is
	          another dictionary with the module's details including:
	          - image (str): The module's image URL or path.
	          - author (str): The module's author name.
	          - price (float): The module's price.
	          - link (str): A link to the module.
	          - id (str): The module's identifier.
	          - desc (str): A description of the module.
	          - selected (bool): A flag indicating whether the module is selected,
	                            initialized to False.
	"""
	TMP = {}
	for mod in tpmmodules:
		TMP[mod["name"]] = {
			"image": mod["image"],
			"author": mod["author"],
			"price": mod["price"],
			"link": mod["link"],
			"id": mod["id"],
			"desc": mod["desc"],
			"selected":False
		}
	return TMP


def getPackagedModules(edition="standard", package="pro"):
	"""Retrieves the packaged modules for a specified edition and package.
	
	This function returns the modules associated with a specified edition from
	the `packageModules` dictionary. The `package` parameter is currently not
	used in the function but can be included for future expansion.
	
	Args:
	    edition (str): The edition of the modules to retrieve. Default is "standard".
	    package (str): The package type of the modules to retrieve. Default is "pro".
	                   (Currently unused in the function)
	
	Returns:
	    list: A list of modules corresponding to the specified edition.

	"""
	return  packageModules[edition]


def get(vendors=[], gwType="standard"):
	""" Returns a dictionary of modules for each specified vendor.
	
	For each valid vendor, all modules published by the vendor are added to the return
	dictionary. Invalid vendors will be returned in the dictionary as 
	"VendorName": "Invalid vendor"
	
	Typical usage examples:
		get()
			This will return all modules from all vendors
		get(["IA", "CL"])
			This will return all Inductive Automation and Cirrus Link modules
		get(["IA", "Acme"])
			This will return all Inductive Automation modules and an entry indicating
			"Acme" is an invalid vendor
	"""
	if not isinstance(vendors, list):
		return "Error: Expected list of vendors"
	elif len(vendors) < 1:
		return gwTypes[gwType]
	returnDict = {}
	for vendor in vendors:
		if vendor in gwTypes[gwType]:
			returnDict[vendor] = gwTypes[gwType][vendor]
		else:
			returnDict[vendor] = "Invalid vendor"
	return returnDict


def getList(vendor, names=[], gwType="standard"):
	""" Return a list of module details from the specified vendor.
	
	If a list of module names is not provided, details of all modules published by the 
	vendor are returned. If a list is provided, details for each module in the list are 
	returned, if found.
	
	Typical usage examples:
		getList("IA")
			This will return a list of all IA modules
		getList("CL", ["MQTT Transmission", "MQTT Distributor"])
			This will return a list including Cirrus Link's MQTT Transmission and
			Distributor modules
	"""
	if vendor not in gwTypes[gwType].keys():
		return "Error: Invalid module vendor '" + vendor + "'"
	else:
		returnList = []
		if len(names) > 0:
			if all(name in gwTypes[gwType][vendor] for name in names):
				for name in names:
					if name in gwTypes[gwType][vendor]:
						module = gwTypes[gwType][vendor][name]
						module["name"] = name
						returnList.append(module)
			else:
				for name in names:
					if name not in gwTypes[gwType][vendor]:
						returnList.append(name)
				return "Error: Invalid module names: '" + "', '".join(returnList) + "'"
		else:
			for m in gwTypes[gwType][vendor]:
				this = gwTypes[gwType][vendor][m]
				this["name"] = m
				returnList.append(this)
		return returnList


def getImageFromName(vendor, name, gwType="standard"):
	""" Return the image for the specified module published by the specified vendor
	
	Typical usage example:
		getImageFromName("IA", "SFC")
			This will return the SFC module image
		getImageFromName("CL", "MQTT")
			This will return "Error: Invalid module name 'MQTT'"
	"""
	if vendor not in gwTypes[gwType].keys():
		return "Error: Invalid module vendor '" + vendor + "'"
	else:
		if name in gwTypes[gwType][vendor]:
			return gwTypes[gwType][vendor][name]["image"]
		else:
			return "Error: Invalid module name '" + name + "'"


