def getRetail(vendor, module, selection=None, gwType="standard"):
	""" Return the price for the specified module published by the specified vendor.
	
	Modules with multiple versions require one to be specified by passing a 
	dictionary with the keys "name" and "version".
	
	Typical usage example:
		getRetail("IA", "SFC")
			This will return the retail cost of Inductive Automation's SFC module
		getRetail("IA", "Perspective", "3 Sessions")
			This will return the retail cost of Inductive Automation's Perspective module
			with a 3-count session limitation
		getRetail("Acme", "Roller Skates")
			This will return an error indicating the module vendor is invalid
	"""
	logger = system.util.getLogger("exchange.architecturebuilder.modules.getRetail")
	if logger.isTraceEnabled():
		logger.trace("Vendor: %s, Module: %s, Selection: %s, Gateway Type: %s" % (vendor, module, selection, gwType))
	if vendor == 'TPM':
		TPMs = system.tag.readBlocking(['[default]Exchange/ArchitectureBuilder/TPM'])[0].value
		if module in TPMs.keys():
			return TPMs[module]['price']
	elif vendor in gwTypes[gwType.lower()].keys():
		if module in gwTypes[gwType.lower()][vendor].keys():
			if selection is None:
				if logger.isTraceEnabled():
					logger.trace("Module Selection N/A")
				return gwTypes[gwType.lower()][vendor][module]['price']
			elif module == "EAM" and selection == "unlimited":
				return getEamUnlimited()
			else:
				if logger.isTraceEnabled():
					logger.trace("Module Selection: %s" % (selection))
				if selection in gwTypes[gwType.lower()][vendor][module]['price']:
					val = gwTypes[gwType.lower()][vendor][module]['price'][selection]
					if logger.isTraceEnabled():
						logger.trace("Selection price = %d" % (val))
					return val
				else:
					return "Error: Invalid module version '" + selection + "'"
		else:
			return "Error: Invalid module name '" + module + "'"
	else:
		return "Error: Invalid module vendor '" + vendor + "'"


def getRetailTotal(selectedModules, gwType="standard"):
	""" Return total cost of specified modules published by the specified vendor.
	
	Modules with multiple versions require one to be specified by passing a 
	dictionary with the keys "name" and "version".
	
	Typical usage example:
		getRetailTotal({"IA": ["SFC", {name": "Perspective", "selection": "1 Session"}]})
			This will return the total retail cost of Inductive Automation's Sequential 
			Function Chart module and Perspective with a 1-session limitation
		getRetailTotal({"IA": ["Platform"], "CL": ["MQTT Distributor"]})
			This will return the total retail cost of Inductive Automation's Platform
			and Cirrus Link's MQTT Distributor module
	"""
	returnDict = {"total": 0, "msg": ""}
	vendorErrors = []
	visualizationModules = 0
	TPMs=system.tag.readBlocking(['[default]Exchange/ArchitectureBuilder/TPM'])[0].value
	if isinstance(selectedModules, dict):
		for vendor in selectedModules.keys():
			if vendor not in gwTypes[gwType.lower()].keys():
				vendorErrors.append(vendor)
			else:
				for m in selectedModules[vendor]:
					if isinstance(m, dict):
						if vendor == 'TPM':
							if module in TPMs.keys():
								result = TPMs[module]['price']
							else:
								result = 0
						else:
							# Handle Unlimited Perspective + Unlimited Vision discount
							if vendor == 'IA' and m['name'] in ("Perspective", "Vision") and m['selection'] == "Unlimited":
								visualizationModules += 1
							result = getRetail(vendor, m['name'], m['selection'], gwType = gwType)
					else:
						result = getRetail(vendor, m, gwType = gwType)

					if isinstance(result, str) or isinstance(result, unicode):
						returnDict['msg'] = result + " for vendor '" + vendor + "'"
					elif isinstance(result, dict):
						returnDict['msg'] = "Invalid module selection"
					else:
						returnDict['total'] += result
		# Handle Unlimited Perspective + Unlimited Vision discount ($3000 deduction)
		if visualizationModules == 2:
			returnDict['total'] -= 3000
		if len(vendorErrors) > 0:
			returnDict['msg'] = "Error: Invalid vendor names: '" + "', '".join(vendorErrors) + "'"
	else:
		returnDict['msg'] = "Error: Expected dictionary of vendors and selected modules"
	return returnDict


def getSupportTotal(selectedModules, supportPlan="Total", gwType="standard"):
    """ Return total cost of support plan based on selected Inductive 
        Automation and Cirrus Link modules.
    
    Modules with multiple versions require one to be specified by passing a 
    dictionary with the keys "name" and "version".
    
    Typical usage example:
        getSupportTotal({"IA": ["SFC", {name": "Perspective", "selection": "1 Session"}]}, "Priority", "standard")
        	This return the total Support Plan cost for an Edge
        getSupporttotal({"IA": ["EAM, 
    """
    returnDict = {"total": 0, "msg": ""}
    if supportPlan not in supportPlans.keys():
        returnDict["msg"] = "Error: Invalid support plan"
    elif not isinstance(selectedModules, dict):
        returnDict["msg"] = "Error: Expected dictionary of vendors and selected modules"
    else:
        # Remove modules by vendors other than Inductive Automation and Cirrus Link
        # because they aren't covered by IA Support Plans
        for vendor in selectedModules:
            if vendor not in ("IA", "CL"):
                del selectedModules[vendor]
        # Get total retail cost
        retail = getRetailTotal(selectedModules, gwType)
        if retail["total"] == 0:
            returnDict["msg"] = retail["msg"]
        else:
            # Multiply module retail cost by support plan multiplier
            returnDict["total"] = retail["total"] * supportPlans[supportPlan]["multiplier"]
    return returnDict


def getSupportPlans():
	"""Returns the various Inductive Automation Support Plans.
	
	This function accesses the supportPlans dictionary and returns the.
	
	Returns:
	    dict: The dictionary containing third-party modules information.
	"""
	return supportPlans


def getGWTypeModules(gwType="Standard"):
	"""
	Retrieves preselected modules for a specified gateway type.
	
	This function returns the modules associated with a specified gateway type
	from the `preselectedmodules` dictionary. The gateway type is converted to
	lowercase to ensure case-insensitive matching.
	
	Args:
	    gwType (str): The type of gateway for which to retrieve modules. Default is "Standard".
	
	Returns:
	    list: A list of modules corresponding to the specified gateway type.
	"""
	gwType=gwType.lower()
	return preselectedmodules[gwType]


def getUpdatedModules(currentModules, edition):
	"""
	Updates the current modules based on the edition and allowed modules.
	
	Args:
		currentModules (dict): A dictionary containing current modules for each vendor.
		edition (str): The edition which determines the allowed modules.
	
	Returns:
		dict: A dictionary containing updated modules for each vendor.
	"""
	# Get allowed modules for the given edition
	allowedModules=gwTypes[edition]
	# Initialize dictionary for updated modules
#	umodules={"IA": [],"CL": [],"SS": [],"TPM": []}
	umodules={"IA": [],"CL": [],"TPM": []}
	# Initialize dictionary for selected modules
#	selModules={"IA": [],"CL": [],"SS": [],"TPM": []}
	selModules={"IA": [],"CL": [],"TPM": []}

	
	# Iterate over current modules to update selections based on allowed modules
	for vendor in currentModules.keys():
		if vendor in allowedModules.keys():
			for module in currentModules[vendor]:
				if module["name"] not in selModules[vendor]:
					if module["name"] in allowedModules[vendor].keys():
						selModules[vendor].append(module["name"])
						if "selection" in module.keys() and "default" in allowedModules[vendor][module["name"]].keys():
							module["selection"] = allowedModules[vendor][module["name"]]["default"]
						umodules[vendor].append(module)
	# Add default modules that are allowed but not in current modules
	for vendor in allowedModules.keys():
		for module in allowedModules[vendor].keys():
			if module not in selModules[vendor]:
				try:
					if "selected" in allowedModules[vendor][module].keys() and allowedModules[vendor][module]["selected"]:
						selModules[vendor].append(module)
						mod = {"name": module}
						if "default" in allowedModules[vendor][module].keys():
							mod["selection"] = allowedModules[vendor][module]["default"]
						umodules[vendor].append(mod)
				except Exception as error:
					logger = system.util.getLogger("ChangeGateway")
					logger.warn(str(error)+ str(allowedModules[vendor][module].keys()))
	return umodules


def getModulesEditionChange(moduleList, preSelectedMods, edition, vendor):
	"""
	Updates module list based on edition change and pre-selected modules.
	
	Args:
		moduleList (list): List of module names.
		preSelectedMods (dict): Dictionary of pre-selected modules for each vendor.
		edition (str): The edition which determines the allowed modules.
		vendor (str): The specific vendor to update modules for.
	
	Returns:
		list: A list of dictionaries containing updated module details.
	"""
	logger = system.util.getLogger("PanelSelect")
	# Get allowed modules for the given edition
	panelVision = False
	gwTypeModules = gwTypes[edition]
	# Initialize list for module instances
	instances = []
	# Iterate over the list of modules to update based on edition and pre-selected modules
	if edition == "panel":
		for mod in preSelectedMods["IA"]:
			if mod["name"] == "Vision":
				panelVision = True

	for module in moduleList:
		enabled = False
		selected = None
		selection = None
		options = []
		
#		# Check if the module is pre-selected for the given vendor
		if vendor in preSelectedMods.keys():
			for item in preSelectedMods[vendor]:
				if item["name"] == module:
					selected = True
					if "selection" in item.keys():
						selection = item["selection"]

		 # Check if the module is allowed for the given vendor and edition
		if vendor in gwTypeModules.keys():
			if module in gwTypeModules[vendor].keys():
				enabled = True

				# Handle module pricing options and default selection
				if "price" in gwTypeModules[vendor][module].keys() and isinstance(gwTypeModules[vendor][module]["price"], dict):
					options=gwTypeModules[vendor][module]["price"].keys()
					if selection is None and "default" in gwTypeModules[vendor][module].keys():
						selection = gwTypeModules[vendor][module]["default"]
				if selected is None or not selected:
					if module == "Perspective" and panelVision and edition == "panel":
						selected = False
					else:
						selected = gwTypeModules[vendor][module]["selected"]

			else:
				enabled=False
				selected=False
		else:
			selected=False
			enabled=False

		# Append updated module details to instances list
		instances.append({
		  "image": modules[vendor][module]["image"].decode("unicode-escape"),
		  "name": module,
		  "selected": selected,
		  "desc": modules[vendor][module]["desc"],
		  "enabled": enabled,
		  "options": sorted(options),
		  "selection": selection
		})

	return instances


def getModulesById(moduleIDList):
	"""
	Retrieves active modules based on a list of module IDs.
	
	Args:
	    moduleIDList (list): List of module IDs to be retrieved.
	
	Returns:
	    dict: A dictionary containing active modules for each provider.
	"""
	# Initialize dictionary for active modules
	activeModules = {}
	for provider in modules.keys():
		# Initialize list for the current provider
		activeModules[provider] = []

		# Special case: Add "Platform" module for "IA" provider
		if provider == "IA":
			activeModules[provider].append({"name": "Platform"})

		# Iterate over each module for the current provider
		for m in modules[provider]:
			# Check if the module has an "id" key and if it is in the moduleIDList
			if "id" in modules[provider][m].keys():
				if modules[provider][m]["id"] in moduleIDList:
					activeModules[provider].append({"name": m})

	return activeModules